  if((rollover||hasWork)&&!confirm(rollover?t('Phiên đã đầy. Bắt đầu phiên mới? Toàn bộ phiên này sẽ được lưu thành bản sao trên thiết bị trước khi chuyển.','This session is full. Start a new session? A complete local archive is saved before switching.'):t('Bắt đầu lượt mới? Lượt hiện tại vẫn được giữ trong sổ tay.','Start a new trial? This trial remains in the notebook.')))return;
