 function download(body,name,type){const blob=new Blob([body],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function exportOriginal(){try{const original=originalRawText||storage?.getItem(key);if(!original)throw Error('missing');download(original,'calorimetry-'+activity+'-unread-original.json','application/json');originalExported=true;message(t('Đã yêu cầu tải bản gốc. Nút JSON xuất phiên đang mở; bản lưu trên thiết bị vẫn được giữ.','Original backup download requested. JSON exports the open session; the device copy is retained.'));}catch{message(t('Chưa đọc được bản gốc để sao lưu. Dữ liệu đang mở vẫn xuất được bằng nút JSON.','Could not read the original backup. You can still export the open session with JSON.'));}}
